<?php
/** TEMP PS S1688 ml — v0.5: f=laukai — Sender laukai PS_HERO_ANTR („Jūsų pamėgtos prekės"/„Pažįstamos prekės") ir PS_HERO_KODEL (footer priežastis) + terra 20 laukų vienu PATCH; recon: 561 sutikusiųjų be pirkimų istorijos, prekių likučiai calc/product segmentuose. f=kurti — 3 testinės kampanijos v0.5 į PS_TEST. */
add_action('init', function(){
  if (!isset($_GET['ps_s1688ml'])) return; global $wpdb; $o=array('v'=>'S1688 ml'); $f=$_GET['ps_s1688ml']; $t=Petshop_Relaunch::t();
  $tok=Petshop_Sender_Adapter::get_stored_token('marketing');
  $api=function($m,$p,$b=null) use($tok){ $a=array('method'=>$m,'timeout'=>25,'headers'=>array('Authorization'=>'Bearer '.$tok,'Accept'=>'application/json','Content-Type'=>'application/json')); if($b!==null) $a['body']=wp_json_encode($b);
    $r=wp_remote_request('https://api.sender.net/v2'.$p,$a); if(is_wp_error($r)) return array('code'=>0,'err'=>$r->get_error_message()); return array('code'=>wp_remote_retrieve_response_code($r),'body'=>json_decode(wp_remote_retrieve_body($r),true)); };
  if($f==='laukai'){
    $r=$api('GET','/fields?limit=100'); $yra=array(); foreach((array)($r['body']['data']??array()) as $x) $yra[$x['title']]=1;
    foreach(array('PS_HERO_ANTR','PS_HERO_KODEL') as $l){ $o[$l]=isset($yra[$l])?'buvo':$api('POST','/fields',array('title'=>$l,'type'=>'text'))['code']; }
    $row=$wpdb->get_row("SELECT * FROM $t WHERE email='terra@gyvunai.lt'",ARRAY_A); $duom=json_decode($row['duomenys'],true); $up=wp_upload_dir();
    $fl=array('PS_HERO_SEG'=>'calc','PS_HERO_PAV'=>$duom['pav'],'PS_HERO_KAINA'=>number_format((float)$duom['kaina'],2,',','').' €','PS_HERO_IMG'=>$up['baseurl'].'/ps-relaunch/12466.jpg','PS_HERO_URL'=>$duom['url'],'PS_HERO_GYV'=>'šuniui','PS_HERO_ANTR'=>'Jūsų pamėgtos prekės','PS_HERO_KODEL'=>'nes esate pirkę petshop.lt');
    foreach($duom['eilutes'] as $i=>$e){ $n=$i+1; $fl["PS_HERO_KG$n"]=$e['kg'].' kg'; $fl["PS_HERO_EUR$n"]='nuo '.$e['eur_nuo'].' €'; $fl["PS_HERO_INFO$n"]=$e['g'].' g/d · maišo užtenka '.$e['d'].' d.'; $fl["PS_HERO_U$n"]=$e['url']; }
    $p=$api('PATCH','/subscribers/terra%40gyvunai.lt',array('fields'=>$fl)); $o['patch']=$p['code']; $g=$api('GET','/subscribers/terra%40gyvunai.lt'); $o['cols_n']=count($g['body']['data']['columns']??array());
    // recon 561
    $o['consent_n']=(int)$wpdb->get_var("SELECT COUNT(*) FROM $t WHERE consent=1");
    $o['consent_be_istorijos']=(int)$wpdb->get_var("SELECT COUNT(*) FROM $t k WHERE consent=1 AND IFNULL(ist_n,0)=0 AND NOT EXISTS (SELECT 1 FROM {$wpdb->prefix}wc_orders o WHERE o.customer_id=k.user_id AND o.status IN ('wc-processing','wc-completed'))");
    $o['consent_seg']=$wpdb->get_results("SELECT segmentas,COUNT(*) n FROM $t WHERE consent=1 GROUP BY segmentas",ARRAY_A);
    $pids=$wpdb->get_col("SELECT DISTINCT product_id FROM $t WHERE consent=1 AND segmentas IN ('calc','product') AND product_id IS NOT NULL"); $st=array('ok'=>0,'nera_sandelyje'=>0,'nepublish'=>0,'gone'=>0);
    foreach($pids as $pid){ $pr=wc_get_product((int)$pid); if(!$pr){$st['gone']++;continue;} if('publish'!==$pr->get_status()||!$pr->is_purchasable()){$st['nepublish']++;continue;} if(!$pr->is_in_stock()){$st['nera_sandelyje']++;continue;} $st['ok']++; } $o['consent_prekes']=$st; $o['consent_prekiu_n']=count($pids);
    $o['pamegtos_n']=(int)$wpdb->get_var("SELECT COUNT(*) FROM $t WHERE consent=1 AND segmentas='product' AND IFNULL(same_sku_orders,0)>=2");
  } else {
    $K=array(
      'calc'=>array('t'=>'TEST relaunch CALC v0.5','s'=>'Kiek kainuoja jūsų augintinio maistas per dieną?','p'=>'Pavyzdys su jums pažįstamu maistu – {{ps_hero_eur1}} per dieną.','h'=>''),
      'product'=>array('t'=>'TEST relaunch PRODUCT v0.5','s'=>'{{ ps_hero_antr | default: "Pažįstamos prekės" }} – atnaujintame Petshop.lt','p'=>'{{ps_hero_pav}} – turime, {{ps_hero_kaina}}. Užsakymų istorija išsaugota, prisijungimas be slaptažodžio.','h'=>''),
      'generic'=>array('t'=>'TEST relaunch GENERIC v0.5','s'=>'Petshop.lt atsinaujino – kas pasikeitė jūsų pirkiniams','p'=>'Ta pati parduotuvė nuo 2010 m., nauja svetainė, jūsų užsakymų istorija išsaugota.','h'=>''));
    $g=$api('GET','/groups/bDxp2q')['body']['data']??array(); $o['aktyviu']=$g['active_subscribers']??null;
    foreach($K as $k=>$c){ $b=array('title'=>$c['t'].' '.date('H:i'),'subject'=>$c['s'],'from'=>'Petshop.lt','reply_to'=>'terra@petshop.lt','content_type'=>'html','content'=>base64_decode($c['h']),'groups'=>array('bDxp2q'),'preheader'=>$c['p']);
      $r=$api('POST','/campaigns',$b); $id=$r['body']['data']['id']??''; $o[$k]=array('kurti'=>$r['code'],'id'=>$id,'err'=>$r['body']['errors']??null);
      if($id && (int)($g['active_subscribers']??0)===1){ $s=$api('POST','/campaigns/'.$id.'/send'); $o[$k]['send']=$s['code'].' '.wp_json_encode($s['body']['message']??$s['body']); } }
  }
  header('Content-Type: application/json; charset=utf-8'); echo json_encode($o,JSON_UNESCAPED_UNICODE|JSON_PRETTY_PRINT); exit;
});
